static void ir_emit_load_i64_lo(ir_ctx *ctx, ir_reg reg, ir_ref src)
{
	if (IR_IS_CONST_REF(src)) {
		ir_insn *insn = &ctx->ir_base[src];

		IR_ASSERT(IR_IS_TYPE_INT(insn->type) && !IR_IS_SYM_CONST(insn->op));
		ir_emit_load_imm_int(ctx, IR_U32, reg, insn->val.u32);
	} else if (ctx->vregs[src] > 0) {
		ir_emit_load_mem_int(ctx, IR_U32, reg, ir_ref_spill_slot(ctx, src));
	} else {
		IR_ASSERT(0);
	}
}

static void ir_emit_load_i64_hi(ir_ctx *ctx, ir_reg reg, ir_ref src)
{
	if (IR_IS_CONST_REF(src)) {
		ir_insn *insn = &ctx->ir_base[src];

		IR_ASSERT(IR_IS_TYPE_INT(insn->type) && !IR_IS_SYM_CONST(insn->op));
		ir_emit_load_imm_int(ctx, IR_U32, reg, insn->val.u32_hi);
	} else if (ctx->vregs[src] > 0) {
		ir_mem mem = IR_MEM_I64_HI(ir_ref_spill_slot(ctx, src));
		ir_emit_load_mem_int(ctx, IR_U32, reg, mem);
	} else {
		IR_ASSERT(0);
	}
}

