{
	if (ctx->vregs[dst] > 0) {
		ir_emit_store_mem_int(ctx, IR_U32, ir_ref_spill_slot(ctx, dst), reg);
	} else {
		IR_ASSERT(0);
	}
}

static void ir_emit_store_i64_hi(ir_ctx *ctx, ir_ref dst, ir_reg reg)
{
	if (ctx->vregs[dst] > 0) {
		ir_mem mem = IR_MEM_I64_HI(ir_ref_spill_slot(ctx, dst));
		ir_emit_store_mem_int(ctx, IR_U32, mem, reg);
	} else {
		IR_ASSERT(0);
	}
}
