		ir_mem mem_hi = IR_MEM_I64_HI(mem);
		ir_reg def_reg_hi = IR_REG_I64_HI(def_reg);

		def_reg = IR_REG_I64_LO(def_reg);
		ir_emit_load_mem_int(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem_int(ctx, IR_U32, def_reg_hi, mem_hi);

