static void ir_emit_tls_load(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg reg = IR_IS_TYPE_INT(insn->type) ? def_reg : ctx->regs[def][3];
	ir_insn *addr_insn = &ctx->ir_base[insn->op2];
	ir_mem mem;

	if (ctx->use_lists[def].count == 1) {
		/* dead load */
		return;
	}

	IR_ASSERT(def_reg != IR_REG_NONE);
	IR_ASSERT(addr_insn->op == IR_TLS_ADDR);

	if (addr_insn->op2 < 0) {
		ir_emit_tls_prefix(ctx);
		mem = IR_MEM_O(addr_insn->op3);
	} else {
		ir_emit_tls_base_addr(ctx, reg, addr_insn->op2);
		mem = IR_MEM_BO(reg, addr_insn->op3);
	}

	ir_emit_load_mem(ctx, insn->type, def_reg, mem);

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store(ctx, insn->type, def, def_reg);
	}
}

static void ir_emit_tls_store(ir_ctx *ctx, ir_ref ref, ir_insn *insn)
{
	ir_type type = ctx->ir_base[insn->op3].type;
	ir_reg op3_reg = ctx->regs[ref][3];
	ir_insn *addr_insn = &ctx->ir_base[insn->op2];
	ir_reg reg = ctx->regs[ref][0];
	ir_mem mem;

	IR_ASSERT(addr_insn->op == IR_TLS_ADDR);

	if (op3_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op3_reg)) {
			op3_reg = IR_REG_NUM(op3_reg);
			ir_emit_load(ctx, type, op3_reg, insn->op3);
		}
	}

	if (addr_insn->op2 < 0) {
		ir_emit_tls_prefix(ctx);
		mem = IR_MEM_O(addr_insn->op3);
	} else {
		ir_emit_tls_base_addr(ctx, reg, addr_insn->op2);
		mem = IR_MEM_BO(reg, addr_insn->op3);
	}

	if (op3_reg != IR_REG_NONE) {
		ir_emit_store_mem(ctx, type, mem, op3_reg);
	} else {
		IR_ASSERT(IR_IS_CONST_REF(insn->op3));
		ir_emit_store_mem_int_const(ctx, type, mem, insn->op3, op3_reg, 0);
	}
}

