static void ir_emit_shift_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg op2_reg = ctx->regs[def][2];
	ir_ref op1_reg_hi, def_reg_hi;

	IR_ASSERT(def_reg != IR_REG_NONE);
	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);
	IR_ASSERT(def_reg != IR_REG_RCX && def_reg_hi != IR_REG_RCX);
	if (op1_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			ir_emit_load_i64_lo(ctx, op1_reg, insn->op1);
			ir_emit_load_i64_hi(ctx, op1_reg_hi, insn->op1);
		} else {
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
		}
	} else {
		op1_reg_hi = IR_REG_NONE;
	}
	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			ir_emit_load_i64_lo(ctx, op2_reg, insn->op2);
		} else {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
	}
	if (op2_reg != IR_REG_RCX) {
		if (op1_reg == IR_REG_RCX) {
			//|	mov Rd(def_reg), Rd(op1_reg)
			op1_reg = def_reg;
		}
		if (op1_reg_hi == IR_REG_RCX) {
			//|	mov Rd(def_reg_hi), Rd(op1_reg_hi)
			op1_reg_hi = def_reg_hi;
		}
		if (op2_reg != IR_REG_NONE) {
			//|	mov ecx, Rd(op2_reg)
		} else {
			ir_emit_load_i64_lo(ctx, IR_REG_RCX, insn->op2);
		}
	}

	ir_emit_load_i64(ctx, def, def_reg, def_reg_hi, op1_reg, op1_reg_hi, insn->op1);

	switch (insn->op) {
		default:
			IR_ASSERT(0);
		case IR_SHL:
			//|	shld Rd(def_reg_hi), Rd(def_reg), cl
			//|	shl	Rd(def_reg), cl
			//|	test cl, 32
			//|	je	>1
			//|	mov Rd(def_reg_hi), Rd(def_reg)
			//|	xor	Rd(def_reg), Rd(def_reg)
			//|1:
			break;
		case IR_SHR:
			//|	shrd Rd(def_reg), Rd(def_reg_hi), cl
			//|	shr	Rd(def_reg_hi), cl
			//|	test cl, 32
			//|	je	>1
			//|	mov Rd(def_reg), Rd(def_reg_hi)
			//|	xor	Rd(def_reg_hi), Rd(def_reg_hi)
			//|1:
			break;
		case IR_SAR:
			//|	shrd Rd(def_reg), Rd(def_reg_hi), cl
			//|	sar	Rd(def_reg_hi), cl
			//|	test cl, 32
			//|	je	>1
			//|	mov Rd(def_reg), Rd(def_reg_hi)
			//|	sar	Rd(def_reg_hi), 31
			//|1:
			break;
	}
	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_shift_const_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	int32_t shift;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op1_reg = ctx->regs[def][1];
	ir_ref op1_reg_hi, def_reg_hi;

	IR_ASSERT(!IR_IS_SYM_CONST(ctx->ir_base[insn->op2].op));
	IR_ASSERT(IR_IS_SIGNED_32BIT(ctx->ir_base[insn->op2].val.i64));
	shift = ctx->ir_base[insn->op2].val.i32;
	IR_ASSERT(def_reg != IR_REG_NONE);

	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);
	if (op1_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			ir_emit_load_i64_lo(ctx, op1_reg, insn->op1);
			ir_emit_load_i64_hi(ctx, op1_reg_hi, insn->op1);
		} else {
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
		}
	} else {
		op1_reg_hi = IR_REG_NONE;
	}

	ir_emit_load_i64(ctx, def, def_reg, def_reg_hi, op1_reg, op1_reg_hi, insn->op1);

	switch (insn->op) {
		default:
			IR_ASSERT(0);
		case IR_SHL:
			if ((shift & 63) != 32) {
				//|	shld Rd(def_reg_hi), Rd(def_reg), shift
				//|	shl	Rd(def_reg), shift
			}
			if (shift & 32) {
				//|	mov Rd(def_reg_hi), Rd(def_reg)
				//|	xor	Rd(def_reg), Rd(def_reg)
			}
			break;
		case IR_SHR:
			if ((shift & 63) != 32) {
				//|	shrd Rd(def_reg), Rd(def_reg_hi), shift
				//|	shr	Rd(def_reg_hi), shift
			}
			if (shift & 32) {
				//|	mov Rd(def_reg), Rd(def_reg_hi)
				//|	xor	Rd(def_reg_hi), Rd(def_reg_hi)
			}
			break;
		case IR_SAR:
			//|	shrd Rd(def_reg), Rd(def_reg_hi), shift
			//|	sar	Rd(def_reg_hi), shift
			if (shift & 32) {
				//|	mov Rd(def_reg), Rd(def_reg_hi)
				//|	sar	Rd(def_reg_hi), 31
			}
			break;
	}
	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_bitcast_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg def_reg_hi, op1_reg_hi;

	if (insn->type == IR_DOUBLE || IR_IS_TYPE_VECTOR(insn->type)) {
		IR_ASSERT(ctx->ir_base[insn->op1].type == IR_I64 || ctx->ir_base[insn->op1].type == IR_U64);

		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
				ir_emit_load_i64_lo(ctx, op1_reg, insn->op1);
				ir_emit_load_i64_hi(ctx, op1_reg_hi, insn->op1);
			} else {
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
			}

			if (ctx->mflags & IR_X86_AVX) {
				//|	vmovd xmm(def_reg-IR_REG_FP_FIRST), Rd(op1_reg)
				//|	vpinsrd xmm(def_reg-IR_REG_FP_FIRST), xmm(def_reg-IR_REG_FP_FIRST), Rd(op1_reg_hi), 1
			} else if (ctx->mflags & IR_X86_SSE41) {
				//|	movd xmm(def_reg-IR_REG_FP_FIRST), Rd(op1_reg)
				//|	pinsrd xmm(def_reg-IR_REG_FP_FIRST), Rd(op1_reg_hi), 1
			} else {
				int32_t offset = ctx->ret_slot;
				ir_reg fp;

				IR_ASSERT(offset != -1);
				offset = IR_SPILL_POS_TO_OFFSET(offset);
				fp = (ctx->flags & IR_USE_FRAME_POINTER) ? IR_REG_FRAME_POINTER : IR_REG_STACK_POINTER;
				ir_emit_store_mem_int(ctx, IR_U32, IR_MEM_BO(fp, offset), op1_reg);
				ir_emit_store_mem_int(ctx, IR_U32, IR_MEM_BO(fp, offset + 4), op1_reg_hi);
				ir_emit_load_mem_fp(ctx, IR_DOUBLE, def_reg, IR_MEM_BO(fp, offset));
			}
		} else if (IR_IS_CONST_REF(insn->op1)) {
			int label = ir_get_const_label(ctx, insn->op1);

			//|	ASM_FP_REG_TXT_OP movs, IR_DOUBLE, def_reg, [=>label]
		} else {
			ir_mem mem;

			if (ir_rule(ctx, insn->op1) & IR_FUSED) {
				mem = ir_fuse_load(ctx, def, insn->op1);
			} else {
				mem = ir_ref_spill_slot(ctx, insn->op1);
			}
			ir_emit_load_mem_fp(ctx, IR_DOUBLE, def_reg, mem);
		}

		if (IR_REG_SPILLED(ctx->regs[def][0])) {
			ir_emit_store(ctx, insn->type, def, def_reg);
		}
	} else {
		IR_ASSERT(insn->type == IR_I64 || insn->type == IR_U64);
		IR_ASSERT(ctx->ir_base[insn->op1].type == IR_DOUBLE || IR_IS_TYPE_VECTOR(ctx->ir_base[insn->op1].type));

		IR_ASSERT(def_reg != IR_REG_NONE);
		def_reg_hi = IR_REG_I64_HI(def_reg);
		def_reg = IR_REG_I64_LO(def_reg);

		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				ir_emit_load(ctx, IR_DOUBLE, op1_reg, insn->op1);
			}

			if (ctx->mflags & IR_X86_AVX) {
				//|	vmovd Rd(def_reg), xmm(op1_reg-IR_REG_FP_FIRST)
				//|	vpextrd Rd(def_reg_hi), xmm(op1_reg-IR_REG_FP_FIRST), 1
			} else if (ctx->mflags & IR_X86_SSE41) {
				//|	movd Rd(def_reg), xmm(op1_reg-IR_REG_FP_FIRST)
				//|	pextrd Rd(def_reg_hi), xmm(op1_reg-IR_REG_FP_FIRST), 1
			} else {
				int32_t offset = ctx->ret_slot;
				ir_reg fp;

				IR_ASSERT(offset != -1);
				offset = IR_SPILL_POS_TO_OFFSET(offset);
				fp = (ctx->flags & IR_USE_FRAME_POINTER) ? IR_REG_FRAME_POINTER : IR_REG_STACK_POINTER;
				ir_emit_store_mem_fp(ctx, IR_DOUBLE, IR_MEM_BO(fp, offset), op1_reg);
				ir_emit_load_mem_int(ctx, IR_U32, def_reg, IR_MEM_BO(fp, offset));
				ir_emit_load_mem_int(ctx, IR_U32, def_reg_hi, IR_MEM_BO(fp, offset + 4));
			}
		} else if (IR_IS_CONST_REF(insn->op1)) {
			ir_insn *val = &ctx->ir_base[insn->op1];

			//|	mov Rd(def_reg), val->val.u32
			//|	mov Rd(def_reg_hi), val->val.u32_hi
		} else {
			ir_mem mem, mem_hi;

			if (ir_rule(ctx, insn->op1) & IR_FUSED) {
				mem = ir_fuse_load(ctx, def, insn->op1);
			} else {
				mem = ir_ref_spill_slot(ctx, insn->op1);
			}
			mem_hi = IR_MEM_I64_HI(mem);
			//|	ASM_REG_MEM_OP mov, IR_U32, def_reg, mem
			//|	ASM_REG_MEM_OP mov, IR_U32, def_reg_hi, mem_hi
		}

		if (IR_REG_SPILLED(ctx->regs[def][0])) {
			ir_emit_store_i64_lo(ctx, def, def_reg);
			ir_emit_store_i64_hi(ctx, def, def_reg_hi);
		}
	}
}

static void ir_emit_int2fp_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_ref op1 = insn->op1;
	ir_type type = ctx->ir_base[op1].type;
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg fp = (ctx->flags & IR_USE_FRAME_POINTER) ? IR_REG_FRAME_POINTER : IR_REG_STACK_POINTER;
	int32_t offset = ctx->ret_slot;
	ir_mem tmp_mem;

	IR_ASSERT(offset != -1);
	offset = IR_SPILL_POS_TO_OFFSET(offset);
	tmp_mem = IR_MEM_BO(fp, offset);

	if (op1_reg != IR_REG_NONE) {
		ir_reg op1_reg_hi;

		if (IR_REG_SPILLED(op1_reg)) {
			ir_mem mem = ir_ref_spill_slot(ctx, op1);

			op1_reg = IR_REG_NUM(op1_reg);
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			ir_emit_load_i64_lo(ctx, op1_reg, insn->op1);
			ir_emit_load_i64_hi(ctx, op1_reg_hi, insn->op1);
			//|	ASM_TMEM_OP fild, qword, mem
		} else {
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			//|	ASM_TMEM_TXT_OP mov, dword, tmp_mem, Rd(op1_reg)
			//|	ASM_TMEM_TXT_OP mov, dword, IR_MEM_I64_HI(tmp_mem), Rd(op1_reg_hi)
			//|	ASM_TMEM_OP fild, qword, tmp_mem
		}
		if (type == IR_U64) {
			//|	test Rd(op1_reg_hi), Rd(op1_reg_hi)
		}
	} else if (IR_IS_CONST_REF(op1)) {
		ir_insn *val = &ctx->ir_base[op1];

		//|	ASM_TMEM_TXT_OP mov, dword, tmp_mem, val->val.u32
		//|	ASM_TMEM_TXT_OP mov, dword, IR_MEM_I64_HI(tmp_mem), val->val.u32_hi
		//|	ASM_TMEM_OP fild, qword, tmp_mem
		if (type == IR_U64) {
			//|	ASM_TMEM_TXT_OP cmp, dword, IR_MEM_I64_HI(tmp_mem), 0
		}
	} else {
		ir_mem mem;

		if (ir_rule(ctx, op1) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op1);
		} else {
			mem = ir_ref_spill_slot(ctx, op1);
		}
		//|	ASM_TMEM_OP fild, qword, mem
		if (type == IR_U64) {
			//|	ASM_TMEM_TXT_OP cmp, dword, IR_MEM_I64_HI(mem), 0
		}
	}

	if (type == IR_U64) {
		//|	ASM_TMEM_TXT_OP mov, dword, IR_MEM_I64_HI(tmp_mem), 0
		if (!data->ull2fp_const) {
			data->ull2fp_const = 1;
			ir_rodata(ctx);
			//|.align 4
			//|->ull2fp_const:
			//|.dword 0x5f800000
			//|.code
		}
		//|	jns >1
		//|	fadd dword [->ull2fp_const]
		//|1:
	}

	if (def_reg != IR_REG_NONE) {
		if (insn->type == IR_DOUBLE) {
			//|	ASM_TMEM_OP fstp, qword, tmp_mem
		} else {
			IR_ASSERT(insn->type == IR_FLOAT);
			//|	ASM_TMEM_OP fstp, dword, tmp_mem
		}

		ir_emit_load_mem_fp(ctx, insn->type, def_reg, tmp_mem);

		if (IR_REG_SPILLED(ctx->regs[def][0])) {
			ir_emit_store(ctx, insn->type, def, def_reg);
		}
	} else {
		ir_mem mem = ir_ref_spill_slot(ctx, def);

		if (insn->type == IR_DOUBLE) {
			//|	ASM_TMEM_OP fstp, qword, mem
		} else {
			IR_ASSERT(insn->type == IR_FLOAT);
			//|	ASM_TMEM_OP fstp, dword, mem
		}
	}
}

static void ir_emit_fp2int_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_ref op1 = insn->op1;
	ir_type type = ctx->ir_base[op1].type;
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg tmp_reg = ctx->regs[def][2];
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg fp, def_reg_hi;
	int32_t offset;

	offset = ctx->ret_slot;
	IR_ASSERT(offset != -1);
	offset = IR_SPILL_POS_TO_OFFSET(offset);
	fp = (ctx->flags & IR_USE_FRAME_POINTER) ? IR_REG_FRAME_POINTER : IR_REG_STACK_POINTER;

	IR_ASSERT(def_reg != IR_REG_NONE);
	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);

	if (type == IR_DOUBLE) {
		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				ir_emit_load(ctx, type, op1_reg, op1);
			}
			if (insn->type == IR_U64) {
				if (!data->ull2d_const) {
					data->ull2d_const = 1;
					ir_rodata(ctx);
					//|.align 8
					//|->ull2d_const:
					//|.dword 0, 0x43e00000
					//|.code
				}
				//|	ASM_FP_REG_TXT_OP ucomis, type, op1_reg, [->ull2d_const]
				//|	jnb >1
			}

			ir_emit_store_mem_fp(ctx, type, IR_MEM_BO(fp, offset), op1_reg);
			//|	fld qword [Ra(fp)+offset]
			//|	fisttp qword [Ra(fp)+offset]
			//|	mov Rd(def_reg), dword [Ra(fp)+offset]
			//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]

			if (insn->type == IR_U64) {
				IR_ASSERT(tmp_reg != IR_REG_NONE);
				//|	jmp >2
				//|1:
				if (ctx->mflags & IR_X86_AVX) {
					//|	ASM_AVX_REG_REG_TXT_OP vsubs, type, tmp_reg, op1_reg, [->ull2d_const]
					ir_emit_store_mem_fp(ctx, type, IR_MEM_BO(fp, offset), tmp_reg);
					//|	fld qword [Ra(fp)+offset]
					//|	fisttp qword [Ra(fp)+offset]
				} else {
					if (tmp_reg != op1_reg) {
						//|	movsd xmm(tmp_reg-IR_REG_FP_FIRST), xmm(op1_reg-IR_REG_FP_FIRST)
					}
					//|	ASM_SSE2_REG_TXT_OP subs, type, tmp_reg, [->ull2d_const]
					ir_emit_store_mem_fp(ctx, type, IR_MEM_BO(fp, offset), tmp_reg);
					//|	fld qword [Ra(fp)+offset]
					//|	fisttp qword [Ra(fp)+offset]
				}
				//|	mov Rd(def_reg), dword [Ra(fp)+offset]
				//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]
				//|	add Rd(def_reg_hi), 0x80000000
				//|2:
			}
		} else if (IR_IS_CONST_REF(op1)) {
			int label = ir_get_const_label(ctx, op1);
			//|	fld qword [=>label]
			//|	fisttp qword [Ra(fp)+offset]
			//|	mov Rd(def_reg), dword [Ra(fp)+offset]
			//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]
		} else {
			ir_mem mem;

			if (ir_rule(ctx, op1) & IR_FUSED) {
				mem = ir_fuse_load(ctx, def, op1);
			} else {
				mem = ir_ref_spill_slot(ctx, op1);
			}
			//|	ASM_TMEM_OP fld, qword, mem
			//|	fisttp qword [Ra(fp)+offset]
			//|	mov Rd(def_reg), dword [Ra(fp)+offset]
			//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]
		}
	} else {
		IR_ASSERT(type == IR_FLOAT);
		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				ir_emit_load(ctx, type, op1_reg, op1);
			}
			if (insn->type == IR_U64) {
				if (!data->ull2f_const) {
					data->ull2f_const = 1;
					ir_rodata(ctx);
					//|.align 4
					//|->ull2f_const:
					//|.dword 0x5f000000
					//|.code
				}
				IR_ASSERT(type == IR_FLOAT);
				//|	ASM_FP_REG_TXT_OP ucomis, type, op1_reg, [->ull2f_const]
				//|	jnb >1
			}

			ir_emit_store_mem_fp(ctx, type, IR_MEM_BO(fp, offset), op1_reg);
			//|	fld dword [Ra(fp)+offset]
			//|	fisttp qword [Ra(fp)+offset]
			//|	mov Rd(def_reg), dword [Ra(fp)+offset]
			//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]

			if (insn->type == IR_U64) {
				IR_ASSERT(tmp_reg != IR_REG_NONE);
				//|	jmp >2
				//|1:
				if (ctx->mflags & IR_X86_AVX) {
					//|	ASM_AVX_REG_REG_TXT_OP vsubs, type, tmp_reg, op1_reg, [->ull2f_const]
					ir_emit_store_mem_fp(ctx, type, IR_MEM_BO(fp, offset), tmp_reg);
					//|	fld dword [Ra(fp)+offset]
					//|	fisttp qword [Ra(fp)+offset]
				} else {
					if (tmp_reg != op1_reg) {
						//|	movss xmm(tmp_reg-IR_REG_FP_FIRST), xmm(op1_reg-IR_REG_FP_FIRST)
					}
					//|	ASM_SSE2_REG_TXT_OP subs, type, tmp_reg, [->ull2f_const]
					ir_emit_store_mem_fp(ctx, type, IR_MEM_BO(fp, offset), tmp_reg);
					//|	fld dword [Ra(fp)+offset]
					//|	fisttp qword [Ra(fp)+offset]
				}
				//|	mov Rd(def_reg), dword [Ra(fp)+offset]
				//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]
				//|	add Rd(def_reg_hi), 0x80000000
				//|2:
			}
		} else if (IR_IS_CONST_REF(op1)) {
			int label = ir_get_const_label(ctx, op1);
			//|	fld dword [=>label]
			//|	fisttp qword [Ra(fp)+offset]
			//|	mov Rd(def_reg), dword [Ra(fp)+offset]
			//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]
		} else {
			ir_mem mem;

			if (ir_rule(ctx, op1) & IR_FUSED) {
				mem = ir_fuse_load(ctx, def, op1);
			} else {
				mem = ir_ref_spill_slot(ctx, op1);
			}
			//|	ASM_TMEM_OP fld, dword, mem
			//|	fisttp qword [Ra(fp)+offset]
			//|	mov Rd(def_reg), dword [Ra(fp)+offset]
			//|	mov Rd(def_reg_hi), dword [Ra(fp)+offset+4]
		}
	}

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_bit_count_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg tmp_reg = ctx->regs[def][2];
	ir_reg op1_reg_hi;

	IR_ASSERT(def_reg != IR_REG_NONE && tmp_reg != IR_REG_NONE);
	if (op1_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			ir_emit_load_i64_lo(ctx, op1_reg, insn->op1);
			ir_emit_load_i64_hi(ctx, op1_reg_hi, insn->op1);
		} else {
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
		}

		switch (insn->op) {
			case IR_CTPOP:
				//|	popcnt Rd(def_reg), Rd(op1_reg)
				//|	popcnt Rd(tmp_reg), Rd(op1_reg_hi)
				//|	add Rd(def_reg), Rd(tmp_reg)
				break;
			case IR_CTLZ:
				//|   bsr Rd(tmp_reg), Rd(op1_reg)
				//|	or Rd(tmp_reg), 32
				//|	bsr Rd(def_reg), Rd(op1_reg_hi)
				//|	cmovz Rd(def_reg), Rd(tmp_reg)
				//|	xor Rd(def_reg), 31
				break;
			case IR_CTTZ:
				//|	bsf Rd(tmp_reg), Rd(op1_reg_hi)
				//|	add Rd(tmp_reg), 32
				//|	bsf Rd(def_reg), Rd(op1_reg)
				//|	cmovz Rd(def_reg), Rd(tmp_reg)
				break;
			default:
				IR_ASSERT(0);
		}
	} else if (IR_IS_CONST_REF(insn->op1)) {
		IR_ASSERT(0);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, insn->op1) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, insn->op1);
		} else {
			mem = ir_ref_spill_slot(ctx, insn->op1);
		}
		mem_hi = IR_MEM_I64_HI(mem);

		switch (insn->op) {
			case IR_CTPOP:
				//|	ASM_TXT_TMEM_OP popcnt, Rd(def_reg), dword, mem
				//|	ASM_TXT_TMEM_OP popcnt, Rd(tmp_reg), dword, mem_hi
				//|	add Rd(def_reg), Rd(tmp_reg)
				break;
			case IR_CTLZ:
				//|   ASM_TXT_TMEM_OP bsr, Rd(tmp_reg), dword, mem
				//|	or Rd(tmp_reg), 32
				//|	ASM_TXT_TMEM_OP bsr, Rd(def_reg), dword, mem_hi
				//|	cmovz Rd(def_reg), Rd(tmp_reg)
				//|	xor Rd(def_reg), 31
				break;
			case IR_CTTZ:
				//|	ASM_TXT_TMEM_OP bsf, Rd(tmp_reg), dword, mem_hi
				//|	add Rd(tmp_reg), 32
				//|	ASM_TXT_TMEM_OP bsf, Rd(def_reg), dword, mem
				//|	cmovz Rd(def_reg), Rd(tmp_reg)
				break;
			default:
				IR_ASSERT(0);
		}
	}

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store(ctx, insn->type, def, def_reg);
	}
}

static void ir_emit_min_max_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_type type = ctx->ir_base[insn->op1].type;
	ir_op op;
	ir_ref op1 = insn->op1;
	ir_ref op2 = insn->op2;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg op2_reg = ctx->regs[def][2];
	ir_reg tmp_reg = ctx->regs[def][3];
	ir_reg op1_reg_hi, op2_reg_hi, def_reg_hi;

	IR_ASSERT(def_reg != IR_REG_NONE && tmp_reg != IR_REG_NONE);
	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);

	if (op1_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			ir_emit_load_i64_lo(ctx, op1_reg, op1);
			ir_emit_load_i64_hi(ctx, op1_reg_hi, op1);
		} else {
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
		}
	} else {
		op1_reg_hi = IR_REG_NONE;
	}
	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			if (op1 != op2) {
				ir_emit_load_i64_lo(ctx, op2_reg, op2);
				ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
			}
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
	} else {
		op2_reg_hi = IR_REG_NONE;
	}

	if (insn->op == IR_MIN) {
		op = (type == IR_I64) ? IR_GT : IR_UGT;
	} else {
		op = (type == IR_I64) ? IR_LT : IR_ULT;
	}

	ir_emit_cmp_i64_common(ctx, op, def, tmp_reg, IR_REG_NONE, op1_reg, op1_reg_hi, op1, op2_reg, op2_reg_hi, op2);

	if (type == IR_I64) {
		//|	jl >1
	} else {
		//|	jc >1
	}

	ir_emit_load_i64(ctx, def, def_reg, def_reg_hi, op1_reg, op1_reg_hi, op1);

	//|	jmp >2
	//|1:

	ir_emit_load_i64(ctx, def, def_reg, def_reg_hi, op2_reg, op2_reg_hi, op2);

	//|2:


	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_cond_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_ref op1 = insn->op1;
	ir_ref op2 = insn->op2;
	ir_ref op3 = insn->op3;
	ir_type op1_type = ctx->ir_base[op1].type;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op1_reg = ctx->regs[def][1];
	ir_reg op2_reg = ctx->regs[def][2];
	ir_reg op3_reg = ctx->regs[def][3];
	ir_ref op2_reg_hi, op3_reg_hi, def_reg_hi;

	IR_ASSERT(def_reg != IR_REG_NONE);
	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);

	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			ir_emit_load_i64_lo(ctx, op2_reg, op2);
			ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
	} else {
		op2_reg_hi = IR_REG_NONE;
	}

	if (op3_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op3_reg)) {
			op3_reg = IR_REG_NUM(op3_reg);
			op3_reg_hi = IR_REG_I64_HI(op3_reg);
			op3_reg = IR_REG_I64_LO(op3_reg);
			if (op2 != op3) {
				ir_emit_load_i64_lo(ctx, op3_reg, op3);
				ir_emit_load_i64_hi(ctx, op3_reg_hi, op3);
			}
		} else {
			op3_reg_hi = IR_REG_I64_HI(op3_reg);
			op3_reg = IR_REG_I64_LO(op3_reg);
		}
	} else {
		op3_reg_hi = IR_REG_NONE;
	}

	if (op1_type == IR_I64 || op1_type == IR_U64) {
		ir_reg op1_reg_hi, tmp_reg;

		IR_ASSERT(ctx->tmp_regs && ctx->tmp_regs[def] != IR_REG_NONE);
		tmp_reg = ctx->tmp_regs[def];

		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
				if (op1 != op2 && op1 != op3) {
					ir_emit_load_i64_lo(ctx, op1_reg, op1);
					ir_emit_load_i64_hi(ctx, op1_reg_hi, op1);
				}
			} else {
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
			}
		}
		if (op1_reg != IR_REG_NONE) {
			//|	mov Rd(tmp_reg), Rd(op1_reg)
			//|	or Rd(tmp_reg), Rd(op1_reg_hi)
		} else {
			ir_mem mem, mem_hi;

			if (ir_rule(ctx, insn->op1) & IR_FUSED) {
				mem = ir_fuse_load(ctx, def, insn->op1);
			} else {
				mem = ir_ref_spill_slot(ctx, insn->op1);
			}
			mem_hi = IR_MEM_I64_HI(mem);

			//|	ASM_REG_MEM_OP mov, IR_U32, tmp_reg, mem
			//|	ASM_REG_MEM_OP or, IR_U32, tmp_reg, mem_hi
		}
		//|	je >2
	} else if (IR_IS_TYPE_INT(op1_type)) {
		if (op1_reg != IR_REG_NONE && IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			ir_emit_load(ctx, op1_type, op1_reg, op1);
		}
		if (op1_reg != IR_REG_NONE) {
			//|	ASM_REG_REG_OP test, op1_type, op1_reg, op1_reg
		} else {
			ir_mem mem;

			if (ir_rule(ctx, insn->op1) & IR_FUSED) {
				mem = ir_fuse_load(ctx, def, insn->op1);
			} else {
				mem = ir_ref_spill_slot(ctx, insn->op1);
			}

			//|	ASM_MEM_IMM_OP cmp, op1_type, mem, 0
		}
		//|	je >2
	} else {
		if (op1_reg != IR_REG_NONE && IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			ir_emit_load(ctx, op1_type, op1_reg, op1);
		}
		if (!data->double_zero_const) {
			data->double_zero_const = 1;
			ir_rodata(ctx);
			//|.align 16
			//|->double_zero_const:
			//|.dword 0, 0
			//|.code
		}
		//|	ASM_FP_REG_TXT_OP ucomis, op1_type, op1_reg, [->double_zero_const]
		//|	jp >1
		//|	je >2
		//|1:
	}

	if (op2_reg != IR_REG_NONE) {
		if (def_reg != op2_reg) {
			ir_emit_mov(ctx, IR_U32, def_reg, op2_reg);
		}
		if (def_reg_hi != op2_reg_hi) {
			ir_emit_mov(ctx, IR_U32, def_reg_hi, op2_reg_hi);
		}
	} else if (IR_IS_CONST_REF(op2)) {
		ir_insn *val = &ctx->ir_base[op2];

		ir_emit_load_imm_int(ctx, IR_U32, def_reg, val->val.u32);
		ir_emit_load_imm_int(ctx, IR_U32, def_reg_hi, val->val.u32_hi);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, op2) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op2);
		} else {
			mem = ir_ref_spill_slot(ctx, op2);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg_hi, mem_hi);
	}

	//|	jmp >3
	//|2:

	if (op3_reg != IR_REG_NONE) {
		if (def_reg != op3_reg) {
			ir_emit_mov(ctx, IR_U32, def_reg, op3_reg);
		}
		if (def_reg_hi != op3_reg_hi) {
			ir_emit_mov(ctx, IR_U32, def_reg_hi, op3_reg_hi);
		}
	} else if (IR_IS_CONST_REF(op3)) {
		ir_insn *val = &ctx->ir_base[op3];

		ir_emit_load_imm_int(ctx, IR_U32, def_reg, val->val.u32);
		ir_emit_load_imm_int(ctx, IR_U32, def_reg_hi, val->val.u32_hi);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, op3) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op3);
		} else {
			mem = ir_ref_spill_slot(ctx, op3);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg_hi, mem_hi);
	}

	//|3:

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_cond_cmp_i64(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_insn *cmp_insn = &ctx->ir_base[insn->op1];
	ir_type type = insn->type;
	ir_ref op2 = insn->op2;
	ir_ref op3 = insn->op3;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op2_reg = ctx->regs[def][2];
	ir_reg op3_reg = ctx->regs[def][3];

	if (op2 != op3) {
		if (op2_reg != IR_REG_NONE && IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			ir_emit_load(ctx, type, op2_reg, op2);
		}
		if (op3_reg != IR_REG_NONE && IR_REG_SPILLED(op3_reg)) {
			op3_reg = IR_REG_NUM(op3_reg);
			ir_emit_load(ctx, type, op3_reg, op3);
		}
	} else if (op2_reg != IR_REG_NONE && IR_REG_SPILLED(op2_reg)) {
		op2_reg = IR_REG_NUM(op2_reg);
		ir_emit_load(ctx, type, op2_reg, op2);
		op3_reg = op2_reg;
	} else if (op3_reg != IR_REG_NONE && IR_REG_SPILLED(op3_reg)) {
		op3_reg = IR_REG_NUM(op3_reg);
		ir_emit_load(ctx, type, op3_reg, op3);
		op2_reg = op3_reg;
	}

	do {
		ir_reg tmp_reg = ctx->regs[def][1];
		ir_reg tmp2_reg = ctx->regs[insn->op1][3];
		ir_ref op1 = cmp_insn->op1;
		ir_ref op2 = cmp_insn->op2;
		ir_reg op1_reg, op2_reg;
		ir_reg op1_reg_hi, op2_reg_hi;

		IR_ASSERT(tmp_reg != IR_REG_NONE);

		if (!IR_IS_CONST_REF(insn->op2) && UNEXPECTED(ctx->rules[insn->op2] & IR_FUSED_REG)) {
			op1_reg = ir_get_fused_reg(ctx, def, insn->op1, 1);
			op2_reg = ir_get_fused_reg(ctx, def, insn->op1, 2);
		} else {
			op1_reg = ctx->regs[insn->op1][1];
			op2_reg = ctx->regs[insn->op1][2];
		}

		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
				ir_emit_load_i64_lo(ctx, op1_reg, op1);
				ir_emit_load_i64_hi(ctx, op1_reg_hi, op1);
			} else {
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
			}
		} else {
			op1_reg_hi = IR_REG_NONE;
		}
		if (op2_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op2_reg)) {
				op2_reg = IR_REG_NUM(op2_reg);
				op2_reg_hi = IR_REG_I64_HI(op2_reg);
				op2_reg = IR_REG_I64_LO(op2_reg);
				if (op1 != op2) {
					ir_emit_load_i64_lo(ctx, op2_reg, op2);
					ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
				}
			} else {
				op2_reg_hi = IR_REG_I64_HI(op2_reg);
				op2_reg = IR_REG_I64_LO(op2_reg);
			}
		} else {
			op2_reg_hi = IR_REG_NONE;
		}

		ir_emit_cmp_i64_common(ctx, cmp_insn->op, def, tmp_reg, tmp2_reg, op1_reg, op1_reg_hi, op1, op2_reg, op2_reg_hi, op2);
	} while (0);

	switch (cmp_insn->op) {
		default:
			IR_ASSERT(0 && "NIY binary op");
		case IR_EQ:
			//|	je >2
			break;
		case IR_NE:
			//|	jne >2
			break;
		case IR_LT:
		case IR_GT:
			//|	jl >2
			break;
		case IR_GE:
		case IR_LE:
			//|	jge >2
			break;
		case IR_ULT:
		case IR_UGT:
			//|	jc >2
			break;
		case IR_UGE:
		case IR_ULE:
			//|	jnc >2
			break;
	}

	if (op3_reg != IR_REG_NONE) {
		if (def_reg != op3_reg) {
			if (IR_IS_TYPE_INT(type)) {
				ir_emit_mov(ctx, type, def_reg, op3_reg);
			} else {
				ir_emit_fp_mov(ctx, type, def_reg, op3_reg);
			}
		}
	} else {
		ir_emit_load_ex(ctx, type, def_reg, op3, def);
	}

	//|	jmp >3
	//|2:

	if (op2_reg != IR_REG_NONE) {
		if (def_reg != op2_reg) {
			if (IR_IS_TYPE_INT(type)) {
				ir_emit_mov(ctx, type, def_reg, op2_reg);
			} else {
				ir_emit_fp_mov(ctx, type, def_reg, op2_reg);
			}
		}
	} else {
		ir_emit_load_ex(ctx, type, def_reg, op2, def);
	}

	//|3:

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store(ctx, type, def, def_reg);
	}
}

static void ir_emit_cond_i64_cmp_int(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_ref op2 = insn->op2;
	ir_ref op3 = insn->op3;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op2_reg = ctx->regs[def][2];
	ir_reg op3_reg = ctx->regs[def][3];
	ir_ref op2_reg_hi, op3_reg_hi, def_reg_hi;

	IR_ASSERT(def_reg != IR_REG_NONE);
	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);

	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			ir_emit_load_i64_lo(ctx, op2_reg, op2);
			ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
	} else {
		op2_reg_hi = IR_REG_NONE;
	}

	if (op3_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op3_reg)) {
			op3_reg = IR_REG_NUM(op3_reg);
			op3_reg_hi = IR_REG_I64_HI(op3_reg);
			op3_reg = IR_REG_I64_LO(op3_reg);
			if (op2 != op3) {
				ir_emit_load_i64_lo(ctx, op3_reg, op3);
				ir_emit_load_i64_hi(ctx, op3_reg_hi, op3);
			}
		} else {
			op3_reg_hi = IR_REG_I64_HI(op3_reg);
			op3_reg = IR_REG_I64_LO(op3_reg);
		}
	} else {
		op3_reg_hi = IR_REG_NONE;
	}

	ir_insn *cmp_insn = &ctx->ir_base[insn->op1];

	if (ctx->ir_base[cmp_insn->op1].type == IR_I64 || ctx->ir_base[cmp_insn->op1].type == IR_U64) {
		ir_reg tmp_reg = ctx->regs[def][1];
		ir_reg tmp2_reg = ctx->regs[insn->op1][3];
		ir_ref op1 = cmp_insn->op1;
		ir_ref op2 = cmp_insn->op2;
		ir_reg op1_reg, op2_reg;
		ir_reg op1_reg_hi, op2_reg_hi;

		IR_ASSERT(tmp_reg != IR_REG_NONE);

		if (UNEXPECTED(ctx->rules[insn->op2] & IR_FUSED_REG)) {
			op1_reg = ir_get_fused_reg(ctx, def, insn->op1, 1);
			op2_reg = ir_get_fused_reg(ctx, def, insn->op1, 2);
		} else {
			op1_reg = ctx->regs[insn->op1][1];
			op2_reg = ctx->regs[insn->op1][2];
		}

		if (op1_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op1_reg)) {
				op1_reg = IR_REG_NUM(op1_reg);
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
				ir_emit_load_i64_lo(ctx, op1_reg, op1);
				ir_emit_load_i64_hi(ctx, op1_reg_hi, op1);
			} else {
				op1_reg_hi = IR_REG_I64_HI(op1_reg);
				op1_reg = IR_REG_I64_LO(op1_reg);
			}
		} else {
			op1_reg_hi = IR_REG_NONE;
		}
		if (op2_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(op2_reg)) {
				op2_reg = IR_REG_NUM(op2_reg);
				op2_reg_hi = IR_REG_I64_HI(op2_reg);
				op2_reg = IR_REG_I64_LO(op2_reg);
				if (op1 != op2) {
					ir_emit_load_i64_lo(ctx, op2_reg, op2);
					ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
				}
			} else {
				op2_reg_hi = IR_REG_I64_HI(op2_reg);
				op2_reg = IR_REG_I64_LO(op2_reg);
			}
		} else {
			op2_reg_hi = IR_REG_NONE;
		}

		ir_emit_cmp_i64_common(ctx, cmp_insn->op, def, tmp_reg, tmp2_reg, op1_reg, op1_reg_hi, op1, op2_reg, op2_reg_hi, op2);

		switch (cmp_insn->op) {
			default:
				IR_ASSERT(0 && "NIY binary op");
			case IR_EQ:
				//|	jne >2
				break;
			case IR_NE:
				//|	je >2
				break;
			case IR_LT:
			case IR_GT:
				//|	jge >2
				break;
			case IR_GE:
			case IR_LE:
				//|	jl >2
				break;
			case IR_ULT:
			case IR_UGT:
				//|	jnc >2
				break;
			case IR_UGE:
			case IR_ULE:
				//|	jc >2
				break;
		}
	} else {
		ir_emit_cmp_int_common2(ctx, def, insn->op1, cmp_insn);

		switch (cmp_insn->op) {
			default:
				IR_ASSERT(0 && "NIY binary op");
			case IR_EQ:
				//|	jne >2
				break;
			case IR_NE:
				//|	je >2
				break;
			case IR_LT:
				//|	jge >2
				break;
			case IR_GE:
				//|	jl >2
				break;
			case IR_LE:
				//|	jg >2
				break;
			case IR_GT:
				//|	jle >2
				break;
			case IR_ULT:
				//|	jae >2
				break;
			case IR_UGE:
				//|	jb >2
				break;
			case IR_ULE:
				//|	ja >2
				break;
			case IR_UGT:
				//|	jbe >2
				break;
		}
	}

	//|1:

	if (op2_reg != IR_REG_NONE) {
		if (def_reg != op2_reg) {
			ir_emit_mov(ctx, IR_U32, def_reg, op2_reg);
		}
		if (def_reg_hi != op2_reg_hi) {
			ir_emit_mov(ctx, IR_U32, def_reg_hi, op2_reg_hi);
		}
	} else if (IR_IS_CONST_REF(op2)) {
		ir_insn *val = &ctx->ir_base[op2];

		ir_emit_load_imm_int(ctx, IR_U32, def_reg, val->val.u32);
		ir_emit_load_imm_int(ctx, IR_U32, def_reg_hi, val->val.u32_hi);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, op2) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op2);
		} else {
			mem = ir_ref_spill_slot(ctx, op2);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg_hi, mem_hi);
	}

	//|	jmp >3
	//|2:

	if (op3_reg != IR_REG_NONE) {
		if (def_reg != op3_reg) {
			ir_emit_mov(ctx, IR_U32, def_reg, op3_reg);
		}
		if (def_reg_hi != op3_reg_hi) {
			ir_emit_mov(ctx, IR_U32, def_reg_hi, op3_reg_hi);
		}
	} else if (IR_IS_CONST_REF(op3)) {
		ir_insn *val = &ctx->ir_base[op3];

		ir_emit_load_imm_int(ctx, IR_U32, def_reg, val->val.u32);
		ir_emit_load_imm_int(ctx, IR_U32, def_reg_hi, val->val.u32_hi);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, op3) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op3);
		} else {
			mem = ir_ref_spill_slot(ctx, op3);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg_hi, mem_hi);
	}

	//|3:

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_cond_i64_cmp_fp(ir_ctx *ctx, ir_ref def, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_ref op2 = insn->op2;
	ir_ref op3 = insn->op3;
	ir_reg def_reg = IR_REG_NUM(ctx->regs[def][0]);
	ir_reg op2_reg = ctx->regs[def][2];
	ir_reg op3_reg = ctx->regs[def][3];
	ir_op op;
	ir_ref op2_reg_hi, op3_reg_hi, def_reg_hi;

	IR_ASSERT(def_reg != IR_REG_NONE);
	def_reg_hi = IR_REG_I64_HI(def_reg);
	def_reg = IR_REG_I64_LO(def_reg);

	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			ir_emit_load_i64_lo(ctx, op2_reg, op2);
			ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
	} else {
		op2_reg_hi = IR_REG_NONE;
	}

	if (op3_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op3_reg)) {
			op3_reg = IR_REG_NUM(op3_reg);
			op3_reg_hi = IR_REG_I64_HI(op3_reg);
			op3_reg = IR_REG_I64_LO(op3_reg);
			if (op2 != op3) {
				ir_emit_load_i64_lo(ctx, op3_reg, op3);
				ir_emit_load_i64_hi(ctx, op3_reg_hi, op3);
			}
		} else {
			op3_reg_hi = IR_REG_I64_HI(op3_reg);
			op3_reg = IR_REG_I64_LO(op3_reg);
		}
	} else {
		op3_reg_hi = IR_REG_NONE;
	}

	op = ir_emit_cmp_fp_common(ctx, def, insn->op1, &ctx->ir_base[insn->op1]);

	switch (op) {
		default:
			IR_ASSERT(0 && "NIY binary op");
		case IR_EQ:
			//|	jne >2
			//|	jp >2
			break;
		case IR_NE:
			//|	jp >1
			//|	je >2
			break;
		case IR_LT:
			//|	jp >2
			//|	jae >2
			break;
		case IR_GE:
			//|	jb >2
			break;
		case IR_LE:
			//|	jp >2
			//|	ja >2
			break;
		case IR_GT:
			//|	jbe >2
			break;
		case IR_ULT:
			//|	jae >2
			break;
		case IR_UGE:
			//|	jp >1
			//|	jb >2
			break;
		case IR_ULE:
			//|	ja >2
			break;
		case IR_UGT:
			//|	jp >1
			//|	jbe >2
			break;
		case IR_ORDERED:
			//|	jp >2
			break;
		case IR_UNORDERED:
			//|	jnp >2
			break;
	}
	//|1:

	if (op2_reg != IR_REG_NONE) {
		if (def_reg != op2_reg) {
			ir_emit_mov(ctx, IR_U32, def_reg, op2_reg);
		}
		if (def_reg_hi != op2_reg_hi) {
			ir_emit_mov(ctx, IR_U32, def_reg_hi, op2_reg_hi);
		}
	} else if (IR_IS_CONST_REF(op2)) {
		ir_insn *val = &ctx->ir_base[op2];

		ir_emit_load_imm_int(ctx, IR_U32, def_reg, val->val.u32);
		ir_emit_load_imm_int(ctx, IR_U32, def_reg_hi, val->val.u32_hi);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, op2) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op2);
		} else {
			mem = ir_ref_spill_slot(ctx, op2);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg_hi, mem_hi);
	}

	//|	jmp >3
	//|2:

	if (op3_reg != IR_REG_NONE) {
		if (def_reg != op3_reg) {
			ir_emit_mov(ctx, IR_U32, def_reg, op3_reg);
		}
		if (def_reg_hi != op3_reg_hi) {
			ir_emit_mov(ctx, IR_U32, def_reg_hi, op3_reg_hi);
		}
	} else if (IR_IS_CONST_REF(op3)) {
		ir_insn *val = &ctx->ir_base[op3];

		ir_emit_load_imm_int(ctx, IR_U32, def_reg, val->val.u32);
		ir_emit_load_imm_int(ctx, IR_U32, def_reg_hi, val->val.u32_hi);
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, op3) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, op3);
		} else {
			mem = ir_ref_spill_slot(ctx, op3);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg, mem);
		ir_emit_load_mem(ctx, IR_U32, def_reg_hi, mem_hi);
	}

	//|3:

	if (IR_REG_SPILLED(ctx->regs[def][0])) {
		ir_emit_store_i64_lo(ctx, def, def_reg);
		ir_emit_store_i64_hi(ctx, def, def_reg_hi);
	}
}

static void ir_emit_if_i64(ir_ctx *ctx, uint32_t b, ir_ref def, ir_insn *insn, uint32_t next_block)
{
	ir_reg op2_reg = ctx->regs[def][2];
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_reg tmp_reg = ctx->regs[def][0];
	ir_reg op2_reg_hi;

	IR_ASSERT(tmp_reg != IR_REG_NONE);
	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			ir_emit_load_i64_lo(ctx, op2_reg, insn->op2);
			ir_emit_load_i64_hi(ctx, op2_reg_hi, insn->op2);
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
		if (tmp_reg == op2_reg) {
			//|	or Rd(tmp_reg), Rd(op2_reg_hi);
		} else if (tmp_reg == op2_reg_hi) {
			//|	or Rd(tmp_reg), Rd(op2_reg);
		} else {
			//|	mov Rd(tmp_reg), Rd(op2_reg);
			//|	or Rd(tmp_reg), Rd(op2_reg_hi);
		}
	} else if (IR_IS_CONST_REF(insn->op2)) {
		uint32_t true_block, false_block;

		ir_get_true_false_blocks(ctx, b, &true_block, &false_block);
		if (ir_const_is_true(&ctx->ir_base[insn->op2])) {
			if (true_block != next_block) {
				//|	jmp =>true_block
			}
		} else {
			if (false_block != next_block) {
				//|	jmp =>false_block
			}
		}
		return;
	} else if (ir_rule(ctx, insn->op2) == IR_STATIC_ALLOCA) {
		uint32_t true_block, false_block;

		ir_get_true_false_blocks(ctx, b, &true_block, &false_block);
		if (true_block != next_block) {
			//|	jmp =>true_block
		}
		return;
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, insn->op2) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, insn->op2);
		} else {
			mem = ir_ref_spill_slot(ctx, insn->op2);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		//|	ASM_REG_MEM_OP mov, IR_U32, tmp_reg, mem
		//|	ASM_REG_MEM_OP or, IR_U32, tmp_reg, mem_hi
	}
	ir_emit_jcc(ctx, b, def, insn, next_block, IR_NE, 1, 0);
}

static bool ir_emit_guard_i64(ir_ctx *ctx, uint32_t b, ir_ref def, ir_insn *insn, uint32_t next_block)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_reg op2_reg = ctx->regs[def][2];
	ir_reg tmp_reg = ctx->regs[def][0];
	ir_reg op2_reg_hi;
	void *addr = ir_jmp_addr(ctx, insn, &ctx->ir_base[insn->op3]);

	IR_ASSERT(tmp_reg != IR_REG_NONE);
	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			ir_emit_load_i64_lo(ctx, op2_reg, insn->op2);
			ir_emit_load_i64_hi(ctx, op2_reg_hi, insn->op2);
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
		if (tmp_reg == op2_reg) {
			//|	or Rd(tmp_reg), Rd(op2_reg_hi);
		} else if (tmp_reg == op2_reg_hi) {
			//|	or Rd(tmp_reg), Rd(op2_reg);
		} else {
			//|	mov Rd(tmp_reg), Rd(op2_reg);
			//|	or Rd(tmp_reg), Rd(op2_reg_hi);
		}
	} else if (IR_IS_CONST_REF(insn->op2)) {
		if (ir_const_is_true(&ctx->ir_base[insn->op2])) {
			if (insn->op == IR_GUARD_NOT) {
				//|	jmp &addr
				return 1;
			}
		} else {
			if (insn->op == IR_GUARD) {
				//|	jmp &addr
				return 1;
			}
		}
		return 0;
	} else {
		ir_mem mem, mem_hi;

		if (ir_rule(ctx, insn->op2) & IR_FUSED) {
			mem = ir_fuse_load(ctx, def, insn->op2);
		} else {
			mem = ir_ref_spill_slot(ctx, insn->op2);
		}
		mem_hi = IR_MEM_I64_HI(mem);
		//|	ASM_REG_MEM_OP mov, IR_U32, tmp_reg, mem
		//|	ASM_REG_MEM_OP or, IR_U32, tmp_reg, mem_hi
	}

	if (insn->op == IR_GUARD) {
		//|	je &addr
	} else {
		//|	jne &addr
	}

	return 0;
}

static bool ir_emit_guard_cmp_i64(ir_ctx *ctx, uint32_t b, ir_ref def, ir_insn *insn, uint32_t next_block)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_insn *cmp_insn = &ctx->ir_base[insn->op2];
	ir_op op = cmp_insn->op;
	ir_ref op1 = cmp_insn->op1;
	ir_ref op2 = cmp_insn->op2;
	ir_reg op1_reg, op2_reg;
	ir_reg op1_reg_hi, op2_reg_hi;
	void *addr = ir_jmp_addr(ctx, insn, &ctx->ir_base[insn->op3]);

	if (UNEXPECTED(ctx->rules[insn->op2] & IR_FUSED_REG)) {
		op1_reg = ir_get_fused_reg(ctx, def, insn->op2, 1);
		op2_reg = ir_get_fused_reg(ctx, def, insn->op2, 2);
	} else {
		op1_reg = ctx->regs[insn->op2][1];
		op2_reg = ctx->regs[insn->op2][2];
	}

	if (op1_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op1_reg)) {
			op1_reg = IR_REG_NUM(op1_reg);
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
			ir_emit_load_i64_lo(ctx, op1_reg, op1);
			ir_emit_load_i64_hi(ctx, op1_reg_hi, op1);
		} else {
			op1_reg_hi = IR_REG_I64_HI(op1_reg);
			op1_reg = IR_REG_I64_LO(op1_reg);
		}
	} else {
		op1_reg_hi = IR_REG_NONE;
	}
	if (op2_reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(op2_reg)) {
			op2_reg = IR_REG_NUM(op2_reg);
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
			if (op1 != op2) {
				ir_emit_load_i64_lo(ctx, op2_reg, op2);
				ir_emit_load_i64_hi(ctx, op2_reg_hi, op2);
			}
		} else {
			op2_reg_hi = IR_REG_I64_HI(op2_reg);
			op2_reg = IR_REG_I64_LO(op2_reg);
		}
	} else {
		op2_reg_hi = IR_REG_NONE;
	}

	ir_reg tmp_reg = ctx->regs[def][0];
	ir_reg tmp2_reg = ctx->regs[insn->op2][3];
	IR_ASSERT(tmp_reg != IR_REG_NONE);
	ir_emit_cmp_i64_common(ctx, op, def, tmp_reg, tmp2_reg, op1_reg, op1_reg_hi, op1, op2_reg, op2_reg_hi, op2);

	if (insn->op == IR_GUARD) {
		op ^= 1; // reverse
	}

	switch (op) {
		default:
			IR_ASSERT(0 && "NIY binary op");
		case IR_EQ:
			//|	je &addr
			break;
		case IR_NE:
			//|	jne &addr
			break;
		case IR_LT:
		case IR_GT:
			//|	jl &addr
			break;
		case IR_GE:
		case IR_LE:
			//|	jge &addr
			break;
		case IR_ULT:
		case IR_UGT:
			//|	jc &addr
			break;
		case IR_UGE:
		case IR_ULE:
			//|	jnc &addr
			break;
	}

	return 0;
}

static void ir_emit_return_i64(ir_ctx *ctx, ir_ref ref, ir_insn *insn)
{
	ir_backend_data *data = ctx->data;
	dasm_State **Dst = &data->dasm_state;
	ir_reg ret_reg = data->ra_data.cc->int_ret_reg;
	ir_reg ret2_reg = data->ra_data.cc->int_ret2_reg;
	ir_reg op2_reg = ctx->regs[ref][2];
	ir_reg op2_reg_hi;

	if (op2_reg != IR_REG_NONE && !IR_REG_SPILLED(op2_reg)) {
		op2_reg_hi = IR_REG_I64_HI(op2_reg);
		op2_reg = IR_REG_I64_LO(op2_reg);
		if (op2_reg != ret_reg) {
			//|	mov Rd(ret_reg), Rd(op2_reg)
		}
		if (op2_reg_hi != ret2_reg) {
			//|	mov Rd(ret2_reg), Rd(op2_reg_hi)
		}
	} else {
		ir_emit_load_i64_lo(ctx, ret_reg, insn->op2);
		ir_emit_load_i64_hi(ctx, ret2_reg, insn->op2);
	}
	ir_emit_return_void(ctx);
}

