static ir_reg ir_emit_load_reg(ir_ctx *ctx, ir_type type, ir_reg reg, ir_ref ref)
{
	if (reg != IR_REG_NONE) {
		if (IR_REG_SPILLED(reg)) {
			reg = IR_REG_NUM(reg);
			ir_emit_load(ctx, type, reg, ref);
		}
	}
	return reg;
}

static void ir_emit_load_def_reg(ir_ctx *ctx, ir_type type, ir_reg def_reg, ir_reg use_reg, ir_ref use)
{
	if (def_reg != use_reg) {
		if (use_reg != IR_REG_NONE) {
			if (IR_REG_SPILLED(use_reg)) {
				use_reg = IR_REG_NUM(use_reg);
				ir_emit_load(ctx, type, use_reg, use);
			}
			if (IR_IS_TYPE_INT(type)) {
				ir_emit_mov(ctx, type, def_reg, use_reg);
			} else {
				ir_emit_fp_mov(ctx, type, def_reg, use_reg);
			}
		} else {
			ir_emit_load(ctx, type, def_reg, use);
		}
	}
}

static uint32_t ir_shufps_mask(ir_ctx *ctx, ir_ref ref)
{
	int8_t *p;
	uint32_t i, s, mask = 0;


	IR_ASSERT(IR_IS_CONST_REF(ref) && IR_IS_TYPE_VECTOR(ctx->ir_base[ref].type));
	p = ir_long_const_ptr(ctx, ref);
	s = ir_type_size[IR_VECTOR_BASE_TYPE(ctx->ir_base[ref].type)];
	for (i = 0; i < 4; i++) {
		mask |= (IR_SHUFFLE_MASK(i) & 3) << (i * 2);
	}
	return mask;
}

static uint32_t ir_shufps_mask_12_0(ir_ctx *ctx, ir_ref ref)
{
	int8_t *p;
	uint32_t i, i1, i2, s, mask1 = 0, mask2 = 0;

	IR_ASSERT(IR_IS_CONST_REF(ref) && IR_IS_TYPE_VECTOR(ctx->ir_base[ref].type));
	p = ir_long_const_ptr(ctx, ref);
	s = ir_type_size[IR_VECTOR_BASE_TYPE(ctx->ir_base[ref].type)];
	for (i = i1 = i2 = 0; i < 4; i++) {
		if (!(IR_SHUFFLE_MASK(i) & 4)) {
			if (i1 && (mask1 & 3) == (IR_SHUFFLE_MASK(i) & 3)) {
				/* pass */
			} else if (i1 == 2 && ((mask1 >> 2) & 3) == (IR_SHUFFLE_MASK(i) & 3)) {
				mask2 |= 1 << (i * 2);
			} else {
				IR_ASSERT(i1 < 2);
				mask1 |= (IR_SHUFFLE_MASK(i) & 3) << (i1 * 2);
				mask2 |= i1 << (i * 2);
				i1++;
			}
		} else {
			if (i2 && ((mask1 >> 4) & 3) == (IR_SHUFFLE_MASK(i) & 3)) {
				mask2 |= 2 << (i * 2);
			} else if (i2 == 2 && ((mask1 >> 6) & 3) == (IR_SHUFFLE_MASK(i) & 3)) {
				mask2 |= 3 << (i * 2);
			} else {
				IR_ASSERT(i2 < 2);
				mask1 |= (IR_SHUFFLE_MASK(i) & 3) << ((i2 + 2) * 2);
				mask2 |= (i2 + 2) << (i * 2);
				i2++;
			}
		}
	}
	return mask1 | (mask2 << 8);
}

static uint32_t ir_shufps_mask_12_n(ir_ctx *ctx, ir_ref ref)
{
	int8_t *p;
	uint32_t s, mask1 = 0, mask2 = 0;

	IR_ASSERT(IR_IS_CONST_REF(ref) && IR_IS_TYPE_VECTOR(ctx->ir_base[ref].type));
	p = ir_long_const_ptr(ctx, ref);
	s = ir_type_size[IR_VECTOR_BASE_TYPE(ctx->ir_base[ref].type)];
	IR_ASSERT((IR_SHUFFLE_MASK(0) & 4) != (IR_SHUFFLE_MASK(1) & 4));
	if (!(IR_SHUFFLE_MASK(0) & 4)) {
		mask1 |= (IR_SHUFFLE_MASK(0) & 3);
		mask1 |= (IR_SHUFFLE_MASK(0) & 3) << 2;
		mask1 |= (IR_SHUFFLE_MASK(1) & 3) << 4;
		mask1 |= (IR_SHUFFLE_MASK(1) & 3) << 6;
		mask2 |= 0x8;
	} else {
		mask1 |= (IR_SHUFFLE_MASK(1) & 3);
		mask1 |= (IR_SHUFFLE_MASK(1) & 3) << 2;
		mask1 |= (IR_SHUFFLE_MASK(0) & 3) << 4;
		mask1 |= (IR_SHUFFLE_MASK(0) & 3) << 6;
		mask2 |= 0x2;
	}
	mask2 |= (IR_SHUFFLE_MASK(2) & 3) << 4;
	mask2 |= (IR_SHUFFLE_MASK(3) & 3) << 6;
	return mask1 | (mask2 << 8);
}

static uint32_t ir_shufps_mask_n_12(ir_ctx *ctx, ir_ref ref)
{
	int8_t *p;
	uint32_t s, mask1 = 0, mask2 = 0;

	IR_ASSERT(IR_IS_CONST_REF(ref) && IR_IS_TYPE_VECTOR(ctx->ir_base[ref].type));
	p = ir_long_const_ptr(ctx, ref);
	s = ir_type_size[IR_VECTOR_BASE_TYPE(ctx->ir_base[ref].type)];
	IR_ASSERT((IR_SHUFFLE_MASK(2) & 4) != (IR_SHUFFLE_MASK(3) & 4));
	mask2 |= (IR_SHUFFLE_MASK(0) & 3);
	mask2 |= (IR_SHUFFLE_MASK(1) & 3) << 2;
	if (!(IR_SHUFFLE_MASK(2) & 4)) {
		mask1 |= (IR_SHUFFLE_MASK(2) & 3);
		mask1 |= (IR_SHUFFLE_MASK(2) & 3) << 2;
		mask1 |= (IR_SHUFFLE_MASK(3) & 3) << 4;
		mask1 |= (IR_SHUFFLE_MASK(3) & 3) << 6;
		mask2 |= 0x80;
	} else {
		mask1 |= (IR_SHUFFLE_MASK(3) & 3);
		mask1 |= (IR_SHUFFLE_MASK(3) & 3) << 2;
		mask1 |= (IR_SHUFFLE_MASK(2) & 3) << 4;
		mask1 |= (IR_SHUFFLE_MASK(2) & 3) << 6;
		mask2 |= 0x20;
	}
	return mask1 | (mask2 << 8);
}

