		mod += IR_VECTOR_LENGTH(ctx->ir_base[insn->op1].type);
		ir_emit_store_mem_fp(ctx, ctx->ir_base[insn->op1].type,
			IR_MEM(IR_REG_RSP, src_offset, IR_REG_NONE, 1), op1_reg);

