					ir_emit_store_mem_int(ctx, IR_U32, dst, tmp_reg);
					src = IR_MEM_I64_HI(src);
					dst = IR_MEM_I64_HI(dst);
					ir_emit_load_mem_int(ctx, IR_U32, tmp_reg, src);
					ir_emit_store_mem_int(ctx, IR_U32, dst, tmp_reg);
